window.MODX=window.MODX||{};
window.MODX.m11=function(P,D){
  const V=document.getElementById('view-m11');if(!V)return;const K='bib:m11:st';
  const get=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch(e){return{}}};
  const put=o=>{try{localStorage.setItem(K,JSON.stringify(o))}catch(e){}};
  const L=window.M11LIB||{items:[],tipos:{},legs:{}};const I=L.items;
  const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  function paint(){const st=get();
    V.querySelectorAll('.dwst').forEach(b=>{const s=st[b.dataset.id]||0;b.querySelectorAll('button').forEach(x=>x.classList.toggle('pri',+x.dataset.s===s))});
    V.querySelectorAll('.dwprog').forEach(p=>{const n=+p.dataset.leg;const it=I.filter(i=>i[6]===n);const r=it.filter(i=>(st[i[0]]||0)===2).length;const k=it.filter(i=>i[7]===3);const kr=k.filter(i=>(st[i[0]]||0)===2).length;p.textContent=`${r} de ${it.length} lidos · chave ${kr}/${k.length} ·`});}
  V.addEventListener('click',e=>{const b=e.target.closest('.dwst button, .dwsel');if(!b)return;const id=b.closest('[data-id]').dataset.id;const st=get();st[id]=+b.dataset.s;put(st);paint();draw();});
  const $=id=>document.getElementById(P+id);
  function draw(){const q=($('dq').value||'').toLowerCase(),lg=$('dleg').value,k=$('dk').value,s=$('dst').value,so=$('dsort').value,key=$('dkey').checked,st=get();
    let f=I.filter(i=>(!q||(i[1]+' '+i[2]+' '+i[4]+' '+i[8]).toLowerCase().includes(q))&&(!lg||i[6]==+lg)&&(!k||i[5]===k)&&(s===''||(st[i[0]]||0)==+s)&&(!key||i[7]===3));
    const srt={prio:(a,b)=>b[7]-a[7]||a[6]-b[6],new:(a,b)=>(b[3]||0)-(a[3]||0),old:(a,b)=>(a[3]||9999)-(b[3]||9999),az:(a,b)=>a[1].localeCompare(b[1])};f.sort(srt[so]);
    $('dn').textContent=`${f.length} de ${I.length} itens · ${I.filter(i=>(st[i[0]]||0)===2).length} lidos no total`;
    $('dlist').innerHTML='<table class="bt"><tr><th>Item</th><th>Trecho</th><th>Status</th></tr>'+f.map(i=>{const v=st[i[0]]||0;return `<tr><td>${i[9]?`<a href="${esc(i[9])}">${esc(i[1])}</a>`:`<b>${esc(i[1])}</b>`} <span class="tag ${i[7]===3?'bctop':''}">${esc(L.tipos[i[5]]||i[5])}</span><div class="progtxt">${esc([i[2],i[3]||'',i[4]].filter(Boolean).join(' · '))}</div><div class="progtxt">${esc(i[8])}</div><button class="btn gbtn" data-gu="${esc(i[9])}" data-gt="${esc(i[1])}" data-gd="${esc(i[8])}" data-gk="${i[5]}" data-gs="${esc(L.legs[i[6]]||'')}" data-ga="#${P}dw-${i[0]}">Como usar</button></td><td><a href="#${P}dw-${i[0]}">${esc(L.legs[i[6]]||'')}</a></td><td data-id="${i[0]}">${['não lido','lendo','lido'].map((t,j)=>`<button class="btn dwsel ${v===j?'pri':''}" data-s="${j}">${t}</button>`).join('')}</td></tr>`}).join('')+'</table>';}
  ['dq','dleg','dk','dst','dsort','dkey'].forEach(x=>{const el=$(x);el.addEventListener(el.tagName==='INPUT'&&el.type!=='checkbox'?'input':'change',draw)});
  $('dexp').onclick=()=>{const t=JSON.stringify(get());(navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).catch(()=>prompt('Copie:',t));};
  $('dimp').onclick=()=>{const t=prompt('Cole o progresso copiado:');if(!t)return;try{const o=JSON.parse(t);put(Object.assign(get(),o));paint();draw()}catch(e){alert('Texto inválido.')}};
  paint();draw();
};
